// The /verify page's in-browser checker (issue #284).
//
// The page is served as a plain server-rendered form: no JavaScript means it
// posts to the server and the server runs `oxsum_verify`, exactly as before.
// This module progressively enhances that skeleton — it loads the
// `oxsum_verify` wasm build (`/verify-wasm/verify_wasm.js`, generated by
// wasm-bindgen from the same crate the server calls) and, when a bundle is
// pasted, runs the proof check locally so the user never has to trust a
// verdict the served page rendered.
//
// Every failure mode — wasm unsupported, the bundle not built on this
// deployment, a network hiccup fetching it — leaves the form's native submit
// alone, so the server-side check is always the floor.

export async function attach() {
  const form = document.querySelector('form[action="/verify"]');
  if (!form || typeof WebAssembly !== "object") {
    return;
  }
  let verify;
  try {
    const module = await import("/verify-wasm/verify_wasm.js");
    verify = await module.default();
  } catch {
    // No wasm bundle on this deployment (the committed placeholder throws):
    // leave the form posting to the server.
    return;
  }

  form.addEventListener("submit", async (event) => {
    const bundle = form.elements.bundle.value.trim();
    const expectedHash = form.elements.expected_hash.value.trim();
    // A usage report answers a different question than a bill and needs the
    // published key, which the page does not hold — it keeps the server path.
    if (!bundle || bundle.includes('"subsetHash"')) {
      return;
    }
    event.preventDefault();
    const card = form.closest(".card") || form.parentElement;
    try {
      const result = JSON.parse(verify.verifyBundle(bundle, expectedHash));
      render(card, result);
    } catch (error) {
      render(card, { ok: false, detail: String(error && error.message || error) });
    }
  });
}

// Renders the wasm verdict into a new card that replaces the form's, mirroring
// the markup the server-rendered result page produces (same classes, same
// paragraphs) so the page looks identical whichever side computed it.
function render(card, result) {
  const view = document.createElement("div");
  view.className = "card";

  const h1 = document.createElement("h1");
  h1.textContent = "Verification result";
  view.appendChild(h1);

  const verdict = document.createElement("p");
  const strong = document.createElement("strong");
  const note = document.createElement("p");
  note.className = "muted";

  if (result.verdict === "pass" || result.ok) {
    verdict.className = "ok";
    strong.textContent = "The bill verifies.";
    // charge/price arrive page-ready, leading space included — the same
    // strings the server-rendered verdict interpolates.
    note.textContent =
      "The content hash recomputes from the entry, and the inclusion proof links it to the tree head." +
      (result.charge || "") +
      (result.price || "");
  } else if (result.verdict === "chargeMismatch") {
    verdict.className = "error";
    strong.textContent = "The charge does not add up.";
    note.textContent =
      "The entry is proven unaltered, but the charge it records does not recompute from the usage and rates it carries.";
  } else {
    verdict.className = "error";
    strong.textContent = "The bill does not verify.";
    note.textContent = result.detail ||
      "Either the bundle was altered, or the hash you recorded does not match this entry.";
  }
  verdict.appendChild(strong);
  view.appendChild(verdict);
  view.appendChild(note);

  const again = document.createElement("p");
  const link = document.createElement("a");
  link.href = "/verify";
  link.textContent = "Verify another";
  again.appendChild(link);
  view.appendChild(again);

  card.replaceWith(view);
}

attach();
